// Parse the incoming pg_notify / webhook payload
const body = $input.first().json.body || $input.first().json;

const ruleId = body.rule_id || body.record?.id || 'unknown';
const ruleSlug = body.rule_slug || body.record?.slug || 'unknown';
const operation = body.operation || body.type || 'UPDATE';
const rulesetIds = body.affected_rulesets || [];
const newFingerprint = body.new_fingerprint || null;
const storyId = body.story_id || null;

return [{
  json: {
    ruleId,
    ruleSlug,
    operation,
    rulesetIds,
    newFingerprint,
    storyId,
    receivedAt: new Date().toISOString()
  }
}];

// Generate ALL IDE instruction files from the instruction payload.
// This mirrors the adapter pattern from scripts/ide-adapters/registry.mjs
// Each adapter produces content for its specific IDE format.

const payload = $input.first().json;
const rules = payload.rules || [];
const story = payload.story || {};
const ruleset = payload.ruleset || {};
const generatedAt = new Date().toISOString();

// --- Shared helpers ---
const AUTO_GEN_MARKER = 'Auto-generated from AISHA Expert Overlay ruleset.';

function autoGenHeader(title, fingerprint) {
  let h = `# ${title}\n\n> ${AUTO_GEN_MARKER}\n> **Do not edit manually** — regenerate via \`npm run gen:ide\`.\n`;
  if (fingerprint) h += `> Fingerprint: \`${fingerprint}\`\n`;
  h += `> Generated: ${generatedAt}\n\n`;
  return h;
}

function groupByCategory(rules) {
  const map = {};
  for (const r of rules) {
    const cat = r.category || 'other';
    if (!map[cat]) map[cat] = [];
    map[cat].push(r);
  }
  return map;
}

function categoryLabel(cat) {
  return cat.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

function getRuleContent(rule) {
  if (rule.ai_instructions?.trim()) return rule.ai_instructions.trim();
  if (rule.summary?.trim()) return rule.summary.trim();
  return '';
}

function renderRules(rules) {
  const grouped = groupByCategory(rules);
  const sections = [];
  for (const [cat, catRules] of Object.entries(grouped)) {
    const blocks = catRules.map(r => {
      const c = getRuleContent(r);
      return c ? `#### ${r.title}\n\n${c}` : '';
    }).filter(Boolean);
    if (blocks.length) sections.push(`### ${categoryLabel(cat)}\n\n${blocks.join('\n\n')}`);
  }
  return sections.join('\n\n');
}

function metaFooter(adapterId, outputPath) {
  return '\n' + JSON.stringify({
    story_id: story.id || null,
    output_path: outputPath,
    adapter: adapterId,
    fingerprint: ruleset.fingerprint || null,
    generated_at: generatedAt
  }, null, 2) + '\n';
}

const fp = ruleset.fingerprint || null;

// --- Adapters ---
const files = {};

// 1. copilot-instructions.md
let copilot = autoGenHeader('Copilot Instructions — AISHA Platform', fp);
copilot += '## \u26A0\uFE0F Expert Rules\n\n' + renderRules(rules) + '\n\n';
copilot += '## \uD83D\uDCCB PR Checklist\n\n';
copilot += '- [ ] All expert rules followed\n- [ ] `npm run test` — passing\n- [ ] `npm run build` — successful\n- [ ] `npm run lint` — no errors\n- [ ] No hardcoded text in JSX (use i18n)\n- [ ] No `any` types\n- [ ] No `console.log` in production code\n';
copilot += metaFooter('copilot', '.github/copilot-instructions.md');
files['.github/copilot-instructions.md'] = copilot;

// 2. AGENTS.md (concise rules for Codex/OpenAI agents)
let agents = autoGenHeader('AGENTS.md — Pokyny pro AI asistenty a v\u00FDvoj\u00E1\u0159e', fp);
agents += renderRules(rules) + '\n';
agents += metaFooter('agents', 'AGENTS.md');
files['AGENTS.md'] = agents;

// 3. CLAUDE.md
let claude = autoGenHeader('CLAUDE.md — AISHA Platform', fp);
claude += renderRules(rules) + '\n';
claude += metaFooter('claude', 'CLAUDE.md');
files['CLAUDE.md'] = claude;

// 4. .cursorrules
let cursor = autoGenHeader('Cursor Rules — AISHA Platform', fp);
cursor += renderRules(rules) + '\n';
cursor += metaFooter('cursorrules', '.cursorrules');
files['.cursorrules'] = cursor;

// 5. .windsurfrules
let windsurf = autoGenHeader('Windsurf Rules — AISHA Platform', fp);
windsurf += renderRules(rules) + '\n';
windsurf += metaFooter('windsurfrules', '.windsurfrules');
files['.windsurfrules'] = windsurf;

// 6. AISHA.agent.md
let aisha = '---\ndescription: "AISHA Dirigent \u2014 proaktivn\u00ED orchestr\u00E1tor a evalu\u00E1tor v\u00FDvoje Aisha platformy."\n---\n\n';
aisha += autoGenHeader('AISHA Dirigent \u2014 Agent Definition', fp);
aisha += 'Jsi **AISHA Dirigent**, autonomn\u00ED orchestra\u010Dn\u00ED AI agent platformy Aisha.\n\n';
const lawRule = rules.find(r => r.slug === 'aisha-development-laws' || (r.title || '').includes('Development Laws'));
if (lawRule) aisha += getRuleContent(lawRule) + '\n\n';
aisha += metaFooter('aisha-agent', '.github/agents/AISHA.agent.md');
files['.github/agents/AISHA.agent.md'] = aisha;

// 7. codex SKILL.md
let skill = '---\nname: aisha-dirigent-autopilot\ndescription: Hybrid Aisha/Codex autopilot for the Aisha platform.\n---\n\n';
skill += autoGenHeader('AISHA Dirigent Autopilot', fp);
skill += '## Core rules\n\n- Treat `AGENTS.md` as the policy source.\n- Prefer Aisha for planning, routing, and compliance.\n- Fall back to local CLI when MCP unavailable.\n\n';
skill += metaFooter('codex-skill', 'codex/skills/aisha-dirigent-autopilot/SKILL.md');
files['codex/skills/aisha-dirigent-autopilot/SKILL.md'] = skill;

const fileList = Object.keys(files);

return [{
  json: {
    ruleId: $('Parse Payload').first().json.ruleId,
    ruleSlug: $('Parse Payload').first().json.ruleSlug,
    operation: $('Parse Payload').first().json.operation,
    ruleCount: rules.length,
    adapterCount: fileList.length,
    generatedFiles: fileList,
    files,
    generatedAt,
    fingerprint: fp
  }
}];

// Emit notification for connected MCP clients and VS Code extensions
const notification = {
  type: 'rule_propagation_complete',
  ruleId: $json.ruleId,
  ruleSlug: $json.ruleSlug,
  operation: $json.operation,
  ruleCount: $json.ruleCount,
  adapterCount: $json.adapterCount,
  generatedFiles: $json.generatedFiles,
  generatedAt: $json.generatedAt,
  fingerprint: $json.fingerprint,
  message: `Expert rule '${$json.ruleSlug}' ${$json.operation.toLowerCase()}d — ${$json.ruleCount} rules regenerated into ${$json.adapterCount} IDE files`
};

return [{ json: notification }];
